package dev.veltraph.client.navigation;
import dev.veltraph.client.rotation.DirectRotationPublicationIdentity;
import dev.veltraph.client.core.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
/** Pure identity/real Core lifecycle cases; no opaque native service receipts are synthesized. */
class SourceAimCleanupIdentityTest {
 final Object root=new Object(),parent=new Object(),player=new Object(),world=new Object(),connection=new Object(),config=new Object(),service=new Object();
 LegacyTravelPublicationIdentity.State state(long g,long e,long serial,boolean enabled){return new LegacyTravelPublicationIdentity.State(root,parent,enabled?parent:null,enabled?parent:null,player,world,connection,config,3,1,service,g,e,serial,null,true,enabled,enabled);}
 DirectRotationPublicationIdentity.Scope scope(long g,long e,long serial){return new DirectRotationPublicationIdentity.Scope(root,parent,parent,parent,player,world,connection,config,service,g,e,serial,9);}
 LegacyRetiredParentInteractionIdentity.Lease lease(){return LegacyRetiredParentInteractionIdentity.Lease.capture(state(4,9,20,true),7,9);}
 DirectRotationPublicationIdentity.Proof positive(){return new DirectRotationPublicationIdentity.Proof(scope(4,9,20),scope(5,10,21),21,DirectRotationPublicationIdentity.Mode.AIM);}
 @Test void firstAimMetadataCustodyReleasesNoUnownedNativeCamera(){var x=lease();assertTrue(x.advanceAimCleanup(scope(4,9,20),scope(5,9,20),null,true,state(5,9,20,true),true,7));assertTrue(x.cleanupOnly());assertTrue(x.cleanupCurrent(state(5,9,20,true),true,7));assertFalse(x.current(state(5,9,20,true),true,7));assertFalse(x.publicationFence(state(5,9,20,true),true,7));assertFalse(x.advanceSourceAimCancellation(scope(5,9,20),scope(6,10,20),true,20,state(6,10,20,true),true,7));assertTrue(x.advanceSourceAimCancellation(scope(5,9,20),scope(6,9,20),false,-1,state(6,9,20,true),true,7));assertTrue(x.cancelled());assertTrue(x.cleanupCurrent(state(6,9,20,true),true,7));}
 @Test void priorAuthenticEvidenceAllowsExactlyItsPositiveCancellation(){var x=lease();var prior=new DirectRotationPublicationIdentity.Proof(scope(3,8,19),scope(4,9,20),20,DirectRotationPublicationIdentity.Mode.AIM);assertTrue(x.seedOwn(prior,false));assertTrue(x.advanceAimCleanup(scope(4,9,20),scope(5,9,20),null,true,state(5,9,20,true),true,7));assertFalse(x.advanceSourceAimCancellation(scope(5,9,20),scope(6,9,20),false,-1,state(6,9,20,true),true,7));assertTrue(x.advanceSourceAimCancellation(scope(5,9,20),scope(6,10,20),true,20,state(6,10,20,true),true,7));}
 @Test void positiveLateSourceRefusalKeepsCleanupAndNeverGameplay(){var x=lease();assertTrue(x.advanceAimCleanup(positive().before(),positive().after(),positive(),false,state(5,10,21,true),true,7));assertFalse(x.current(state(5,10,21,true),true,7));assertFalse(x.advance(positive(),true,state(5,10,21,true),true,7));assertTrue(x.advanceSourceAimCancellation(scope(5,10,21),scope(6,11,21),true,21,state(6,11,21,true),true,7));}
 @Test void nativeDisabledOriginalScopeRetainsOnlyCleanup(){var x=lease();assertTrue(x.advanceAimCleanup(positive().before(),positive().after(),positive(),false,state(5,10,21,false),true,7));var before=new DirectRotationPublicationIdentity.Scope(root,parent,null,null,player,world,connection,config,service,5,10,21,9);var after=new DirectRotationPublicationIdentity.Scope(root,parent,null,null,player,world,connection,config,service,6,11,21,9);assertTrue(x.advanceSourceAimCancellation(before,after,true,21,state(6,11,21,false),true,7));assertFalse(x.current(state(6,11,21,false),true,7));}
 @Test void admissionABACallbackCannotBeAdopted(){var x=lease();long[] admission={7};Runnable callback=()->{admission[0]++;admission[0]++;};callback.run();assertFalse(x.advanceAimCleanup(scope(4,9,20),scope(5,9,20),null,true,state(5,9,20,true),true,admission[0]));assertEquals(4,x.generation());assertFalse(x.cleanupOnly());}
 @Test void newerPublicationAndMetadataSkipsRemainRefused(){var x=lease();assertFalse(x.advanceAimCleanup(scope(4,9,20),scope(6,9,20),null,true,state(6,9,20,true),true,7));assertFalse(x.advanceAimCleanup(scope(4,9,20),scope(5,9,21),null,true,state(5,9,21,true),true,7));assertFalse(x.advanceAimCleanup(scope(4,9,20),scope(5,10,20),null,true,state(5,10,20,true),true,7));assertEquals(4,x.generation());}
 @Test void foreignStoreWorldAndServiceCannotCrossOutcome(){for(int field=0;field<3;field++){var x=lease();var changed=new DirectRotationPublicationIdentity.Scope(root,parent,parent,parent,player,field==0?new Object():world,connection,field==1?new Object():config,field==2?new Object():service,5,9,20,9);assertFalse(x.advanceAimCleanup(scope(4,9,20),changed,null,true,state(5,9,20,true),true,7));assertEquals(4,x.generation());}}
 @Test void skippedPositivePublicationCannotHideForeignTicket(){var x=lease();var skipped=new DirectRotationPublicationIdentity.Proof(scope(4,9,20),scope(5,10,22),22,DirectRotationPublicationIdentity.Mode.AIM);assertFalse(x.advanceAimCleanup(skipped.before(),skipped.after(),skipped,false,state(5,10,22,true),true,7));assertEquals(20,x.serial());assertFalse(x.cleanupOnly());}
 @Test void foreignRosterAfterPublicationLeavesOldExpectation(){var x=lease();assertFalse(x.advanceAimCleanup(positive().before(),positive().after(),positive(),false,state(5,10,21,true),false,7));assertEquals(20,x.serial());assertFalse(x.cleanupOnly());}
 @Test void cancellationMustConsumeOneExactOwnedTransition(){var x=lease();assertTrue(x.advanceAimCleanup(positive().before(),positive().after(),positive(),false,state(5,10,21,true),true,7));assertFalse(x.advanceSourceAimCancellation(scope(5,10,21),scope(6,12,21),true,21,state(6,12,21,true),true,7));assertFalse(x.advanceSourceAimCancellation(scope(5,10,21),scope(6,11,22),true,22,state(6,11,22,true),true,7));assertTrue(x.advanceSourceAimCancellation(scope(5,10,21),scope(6,11,21),true,21,state(6,11,21,true),true,7));assertFalse(x.advanceSourceAimCancellation(scope(6,11,21),scope(7,12,21),true,21,state(7,12,21,true),true,7));}
 @Test void realDisableThenReenableCannotReuseFactoryHeldLifecycle(){var manager=new ModuleManager();var actor=new Actor(manager);manager.register(actor);actor.setEnabled(true);actor.original=manager.lifecycleSnapshot();actor.setEnabled(false);assertTrue(actor.cleanupInsideDisable);assertTrue(manager.ownCleanupLifecycleCurrent(actor.original,actor));actor.setEnabled(true);assertFalse(manager.ownCleanupLifecycleCurrent(actor.original,actor));}
 @Test void genuineDisableReentryRevokesOriginalCleanup(){var manager=new ModuleManager();var actor=new Actor(manager);manager.register(actor);actor.setEnabled(true);actor.original=manager.lifecycleSnapshot();actor.reenter=true;actor.setEnabled(false);assertTrue(actor.cleanupInsideDisable);assertFalse(manager.ownCleanupLifecycleCurrent(actor.original,actor));}
 @Test void finalStoredPolicyLeafRefusesMutationAfterEarlierCallbackProof(){var x=lease();var config=new dev.veltraph.client.config.MapConfigService();var captured=config.storedDoubleSnapshot(dev.veltraph.client.config.RotationConfig.ROTATION_SPEED_MULTIPLIER);assertTrue(captured.current());java.util.function.Supplier<Object> lastAuthority=()->{config.set(dev.veltraph.client.config.RotationConfig.ROTATION_SPEED_MULTIPLIER,2d);return parent;};assertSame(parent,lastAuthority.get());boolean accepted=captured.current()&&x.advanceAimCleanup(scope(4,9,20),scope(5,9,20),null,true,state(5,9,20,true),true,7);assertFalse(accepted);assertEquals(4,x.generation());assertFalse(x.cleanupOnly());}
 @Test void finalStoredPolicyLeafRefusesABAAcrossLastAuthority(){var x=lease();var config=new dev.veltraph.client.config.MapConfigService();var captured=config.storedDoubleSnapshot(dev.veltraph.client.config.RotationConfig.ROTATION_SPEED_MULTIPLIER);Runnable callback=()->{config.set(dev.veltraph.client.config.RotationConfig.ROTATION_SPEED_MULTIPLIER,2d);config.reset(dev.veltraph.client.config.RotationConfig.ROTATION_SPEED_MULTIPLIER);};callback.run();assertEquals(1d,config.get(dev.veltraph.client.config.RotationConfig.ROTATION_SPEED_MULTIPLIER));assertFalse(captured.current());assertEquals(4,x.generation());}
 static final class Actor extends AbstractModule {final ModuleManager root;ModuleManager.LifecycleSnapshot original;boolean cleanupInsideDisable,reenter;Actor(ModuleManager r){super("aim_parent","Aim Parent",ModuleCategory.INTERMEDIARY);root=r;}@Override public void onEnable(){}@Override public void onDisable(){cleanupInsideDisable=root.ownCleanupLifecycleCurrent(original,this);if(reenter)setEnabled(true);}}
}
